const toURL = (path) => new URL(path, self.registration.scope).href;

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      await cache.addAll(
        PRECACHE.map((path) => new Request(toURL(path), { cache: "reload" }))
      );
      // First ever install: nothing is running yet, so activate right away
      // and make the game available offline immediately.
      if (!self.registration.active) {
        await self.skipWaiting();
      }
    })()
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      const oldCaches = names.filter((n) => n.startsWith("orbium-") && n !== CACHE_NAME);
      await Promise.all(oldCaches.map((n) => caches.delete(n)));
      // Only take control of pages directly on a first install. After an update
      // the new worker activates only when no page is controlled anymore.
      if (oldCaches.length === 0) {
        await self.clients.claim();
      }
    })()
  );
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE_NAME);
      const cached = await cache.match(request, { ignoreSearch: true });
      if (cached) return cached;

      if (request.mode === "navigate") {
        const shell = await cache.match(toURL("index.html"));
        if (shell) return shell;
      }

      try {
        return await fetch(request);
      } catch {
        return Response.error();
      }
    })()
  );
});
